#!/usr/bin/env bash
# ============================================================
#  Сборка собственной Linux-ОС (live + установщик) на базе Debian 12
#  Результат: готовый ISO, который можно записать на флешку,
#  загрузиться с неё и установить систему на диск (Calamares).
#
#  Запускать от root на Debian 12 (лучше в виртуалке или контейнере):
#      sudo ./build-myos.sh
#  Нужно ~15 ГБ свободного места и интернет.
# ============================================================
set -euo pipefail

# ---------- Настройки (меняйте под себя) ----------
OS_NAME="${OS_NAME:-MyOS}"            # Название системы
DEBIAN_RELEASE="${DEBIAN_RELEASE:-bookworm}"
LOCALE="${LOCALE:-ru_RU.UTF-8}"
TIMEZONE="${TIMEZONE:-Europe/Moscow}"
LIVE_USER="${LIVE_USER:-user}"        # Пользователь в live-режиме (пароль: live)
BUILD_DIR="${BUILD_DIR:-$PWD/myos-build}"

if [[ $EUID -ne 0 ]]; then
  echo "Запустите от root: sudo $0" >&2
  exit 1
fi

# Ресурсы (обои, значки, тема меню) встроены в конец этого файла
ASSETS="$(mktemp -d)"
trap 'rm -rf "$ASSETS"' EXIT
sed '1,/^__ASSETS__$/d' "$0" | base64 -d | tar xz -C "$ASSETS"

echo "==> Устанавливаю инструменты сборки"
apt-get update
apt-get install -y live-build debootstrap debian-archive-keyring \
  squashfs-tools xorriso mtools dosfstools grub-pc-bin grub-efi-amd64-bin

mkdir -p "$BUILD_DIR"
cd "$BUILD_DIR"
lb clean --purge >/dev/null 2>&1 || true

echo "==> Настраиваю сборку"
lb config \
  --distribution "$DEBIAN_RELEASE" \
  --architectures amd64 \
  --archive-areas "main contrib non-free non-free-firmware" \
  --debian-installer none \
  --binary-images iso-hybrid \
  --bootloaders "syslinux,grub-efi" \
  --iso-volume "$OS_NAME" \
  --iso-application "$OS_NAME" \
  --iso-publisher "$OS_NAME" \
  --image-name "$OS_NAME" \
  --security true --updates true \
  --apt-recommends true \
  --bootappend-live "boot=live components quiet splash locales=$LOCALE keyboard-layouts=us,ru keyboard-options=grp:alt_shift_toggle timezone=$TIMEZONE username=$LIVE_USER"

# ---------- Список программ ----------
mkdir -p config/package-lists
cat > config/package-lists/myos.list.chroot <<'EOF'
# Ядро и live-система
linux-image-amd64
live-boot
live-config
live-config-systemd
systemd-sysv
sudo
locales
console-setup
keyboard-configuration

# Рабочий стол
xorg
xfce4
xfce4-terminal
xfce4-notifyd
xfce4-power-manager
xfce4-screenshooter
thunar
thunar-archive-plugin
mousepad
ristretto
lightdm
lightdm-gtk-greeter
network-manager
network-manager-gnome
gvfs-backends
policykit-1-gnome
file-roller
xdg-user-dirs
xdg-utils
fonts-noto
fonts-noto-color-emoji
fonts-liberation
adwaita-icon-theme
arc-theme
papirus-icon-theme
imagemagick
plank
rofi
dconf-cli

# Звук
pulseaudio
pavucontrol

# Программы
firefox-esr
firefox-esr-l10n-ru
libreoffice-writer
libreoffice-calc
libreoffice-l10n-ru
vlc
gparted
git
curl
wget
nano
htop
neofetch
unzip
p7zip-full

# Установщик на диск
calamares
calamares-settings-debian

# Прошивки (Wi-Fi, видео, звук) - чтобы работало на реальном железе
firmware-linux-free
firmware-linux-nonfree
firmware-misc-nonfree
firmware-iwlwifi
firmware-realtek
firmware-atheros
firmware-amd-graphics
firmware-sof-signed
intel-microcode
amd64-microcode
EOF

# ---------- Фирменное оформление: имя системы ----------
mkdir -p config/includes.chroot/etc
cat > config/includes.chroot/etc/os-release <<EOF
PRETTY_NAME="$OS_NAME"
NAME="$OS_NAME"
ID=myos
ID_LIKE=debian
HOME_URL="https://example.com"
EOF
echo "$OS_NAME" > config/includes.chroot/etc/hostname

# ---------- Раскладка клавиатуры и язык для установленной системы ----------
mkdir -p config/includes.chroot/etc/default
cat > config/includes.chroot/etc/default/keyboard <<'EOF'
XKBMODEL="pc105"
XKBLAYOUT="us,ru"
XKBVARIANT=","
XKBOPTIONS="grp:alt_shift_toggle"
EOF

# ---------- Оформление: тёмная тема Arc-Dark + значки Papirus + обои ----------
XFCONF=config/includes.chroot/etc/skel/.config/xfce4/xfconf/xfce-perchannel-xml
mkdir -p "$XFCONF"

cat > "$XFCONF/xsettings.xml" <<'EOF'
<?xml version="1.0" encoding="UTF-8"?>
<channel name="xsettings" version="1.0">
  <property name="Net" type="empty">
    <property name="ThemeName" type="string" value="Arc-Dark"/>
    <property name="IconThemeName" type="string" value="Papirus-Dark"/>
  </property>
  <property name="Gtk" type="empty">
    <property name="FontName" type="string" value="Noto Sans 10"/>
    <property name="CursorThemeName" type="string" value="Adwaita"/>
  </property>
</channel>
EOF

cat > "$XFCONF/xfwm4.xml" <<'EOF'
<?xml version="1.0" encoding="UTF-8"?>
<channel name="xfwm4" version="1.0">
  <property name="general" type="empty">
    <property name="theme" type="string" value="Arc-Dark"/>
    <property name="title_font" type="string" value="Noto Sans Bold 10"/>
    <property name="use_compositing" type="bool" value="true"/>
  </property>
</channel>
EOF

# Обои ставятся при первом входе (имя монитора заранее неизвестно)
mkdir -p config/includes.chroot/usr/local/bin config/includes.chroot/etc/skel/.config/autostart
cat > config/includes.chroot/usr/local/bin/myos-wallpaper <<'EOF'
#!/bin/sh
MARK="$HOME/.config/myos-wallpaper-done"
[ -f "$MARK" ] && exit 0
sleep 4
for p in $(xfconf-query -c xfce4-desktop -l | grep 'last-image$'); do
  xfconf-query -c xfce4-desktop -p "$p" -s /usr/share/backgrounds/myos.jpg
done
touch "$MARK"
EOF
chmod +x config/includes.chroot/usr/local/bin/myos-wallpaper

cat > config/includes.chroot/etc/skel/.config/autostart/myos-wallpaper.desktop <<'EOF'
[Desktop Entry]
Type=Application
Name=MyOS Wallpaper
Exec=/usr/local/bin/myos-wallpaper
X-GNOME-Autostart-enabled=true
EOF

# Экран входа в тёмном стиле
mkdir -p config/includes.chroot/etc/lightdm
cat > config/includes.chroot/etc/lightdm/lightdm-gtk-greeter.conf <<'EOF'
[greeter]
theme-name=Arc-Dark
icon-theme-name=Papirus-Dark
font-name=Noto Sans 10
background=/usr/share/backgrounds/myos.jpg
EOF

# ---------- Ваши обои, значки, док по центру снизу и меню ----------
INC=config/includes.chroot
mkdir -p "$INC/usr/share/backgrounds" "$INC/usr/share/myos/icons" \
         "$INC/usr/share/myos/rofi" "$INC/usr/share/applications"
cp "$ASSETS/wallpaper.jpg" "$INC/usr/share/backgrounds/myos.jpg"
cp "$ASSETS"/icons/*.png "$INC/usr/share/myos/icons/"
cp "$ASSETS/rofi/menu.rasi" "$INC/usr/share/myos/rofi/menu.rasi"

# --- Ярлыки для дока (скрыты из меню приложений) ---
mk_dock_launcher() {  # имя, название, команда, значок, класс окна
  cat > "$INC/usr/share/applications/myos-dock-$1.desktop" <<EOT
[Desktop Entry]
Type=Application
Name=$2
Exec=$3
Icon=/usr/share/myos/icons/$4.png
Terminal=false
NoDisplay=true
EOT
  if [ -n "$5" ]; then echo "StartupWMClass=$5" >> "$INC/usr/share/applications/myos-dock-$1.desktop"; fi
}
mk_dock_launcher menu     "Меню"      'sh -c "pkill -x rofi || rofi -show drun -show-icons -theme /usr/share/myos/rofi/menu.rasi"' dock-menu ""
mk_dock_launcher terminal "Терминал"  "xfce4-terminal" dock-terminal Xfce4-terminal
mk_dock_launcher files    "Файлы"     "thunar %U"      dock-files    Thunar
mk_dock_launcher firefox  "Интернет"  "firefox-esr %u" dock-firefox  firefox-esr
mk_dock_launcher player   "Плеер"     "vlc %U"         dock-player   vlc

# --- Док Plank: по центру внизу, без фона, значки как на вашей картинке ---
PLANK=$INC/etc/skel/.config/plank/dock1/launchers
mkdir -p "$PLANK"
i=1
for n in menu terminal files firefox player; do
  printf '[PlankDockItemPreferences]\nLauncher=file:///usr/share/applications/myos-dock-%s.desktop\n' "$n" \
    > "$PLANK/0$i-$n.dockitem"
  i=$((i+1))
done

mkdir -p "$INC/etc/dconf/profile" "$INC/etc/dconf/db/local.d"
printf 'user-db:user\nsystem-db:local\n' > "$INC/etc/dconf/profile/user"
cat > "$INC/etc/dconf/db/local.d/00-myos" <<'EOT'
[net/launchpad/plank/docks/dock1]
theme='Transparent'
position='bottom'
alignment='center'
items-alignment='center'
icon-size=64
zoom-enabled=true
zoom-percent=130
hide-mode='none'
dock-items=['01-menu.dockitem','02-terminal.dockitem','03-files.dockitem','04-firefox.dockitem','05-player.dockitem']
EOT

cat > "$INC/etc/skel/.config/autostart/plank.desktop" <<'EOT'
[Desktop Entry]
Type=Application
Name=Dock
Exec=plank
X-GNOME-Autostart-enabled=true
X-GNOME-Autostart-Delay=2
EOT

# --- Рабочий стол: только наши шестиугольные ярлыки ---
cat > "$XFCONF/xfce4-desktop.xml" <<'EOT'
<?xml version="1.0" encoding="UTF-8"?>
<channel name="xfce4-desktop" version="1.0">
  <property name="desktop-icons" type="empty">
    <property name="style" type="int" value="2"/>
    <property name="icon-size" type="uint" value="80"/>
    <property name="file-icons" type="empty">
      <property name="show-home" type="bool" value="false"/>
      <property name="show-filesystem" type="bool" value="false"/>
      <property name="show-trash" type="bool" value="false"/>
      <property name="show-removable" type="bool" value="false"/>
    </property>
  </property>
</channel>
EOT

DESK=$INC/etc/skel/Desktop
mkdir -p "$DESK"
mk_desktop_icon() {  # файл, название, команда, значок
  cat > "$DESK/$1.desktop" <<EOT
[Desktop Entry]
Type=Application
Name=$2
Exec=$3
Icon=/usr/share/myos/icons/$4.png
Terminal=false
EOT
  chmod +x "$DESK/$1.desktop"
}
mk_desktop_icon files    "Файлы"                  "thunar"                 hex-files
mk_desktop_icon internet "Интернет"               "firefox-esr"            hex-firefox
mk_desktop_icon terminal "Терминал"               "xfce4-terminal"         hex-terminal
mk_desktop_icon install  "Установить $OS_NAME"    "sudo -E calamares"      hex-install
mk_desktop_icon settings "Настройки"              "xfce4-settings-manager" hex-settings

# ---------- Хук: настройка внутри собираемой системы ----------
mkdir -p config/hooks/normal
cat > config/hooks/normal/0100-myos-setup.hook.chroot <<EOF
#!/bin/sh
set -e
# Включаем русскую локаль
sed -i 's/^# *ru_RU.UTF-8/ru_RU.UTF-8/; s/^# *en_US.UTF-8/en_US.UTF-8/' /etc/locale.gen
locale-gen
update-locale LANG=$LOCALE
# Менеджер сети и экран входа включаем при старте
systemctl enable NetworkManager lightdm || true
# Чистим кэш, чтобы ISO был меньше
apt-get clean
EOF
chmod +x config/hooks/normal/0100-myos-setup.hook.chroot

cat > config/hooks/normal/0200-myos-icons.hook.chroot <<'EOF'
#!/bin/sh
set -e
D=/usr/share/myos/icons
[ -f "$D/dock-firefox-base.png" ] || { echo "myos: значки не найдены, пропускаю"; exit 0; }

# Настоящий логотип Firefox из установленной системы
FF=""
for f in /usr/share/icons/hicolor/128x128/apps/firefox-esr.png \
         /usr/lib/firefox-esr/browser/chrome/icons/default/default128.png \
         /usr/share/icons/hicolor/64x64/apps/firefox-esr.png; do
  if [ -f "$f" ]; then FF="$f"; break; fi
done
if [ -z "$FF" ]; then
  FF="$(find /usr/share/icons /usr/lib/firefox-esr -iname '*firefox*.png' 2>/dev/null | head -n1)"
fi

if [ -n "$FF" ]; then
  convert "$D/dock-firefox-base.png" \( "$FF" -resize 160x160 \) -gravity center -composite "$D/dock-firefox.png"
  convert "$D/hex-firefox-base.png"  \( "$FF" -resize 140x140 \) -gravity center -composite "$D/hex-firefox.png"
else
  convert "$D/dock-firefox-base.png" -fill white -pointsize 64 -gravity center -annotate 0 "Web" "$D/dock-firefox.png"
  convert "$D/hex-firefox-base.png"  -fill white -pointsize 64 -gravity center -annotate 0 "Web" "$D/hex-firefox.png"
fi
rm -f "$D"/*-base.png

chmod +x /etc/skel/Desktop/*.desktop || true
dconf update || true
gtk-update-icon-cache -f /usr/share/icons/hicolor || true
EOF
chmod +x config/hooks/normal/0200-myos-icons.hook.chroot

echo "==> Собираю ISO (это займёт 20-60 минут)"
lb build 2>&1 | tee build.log

ISO="$(ls -1 *.iso 2>/dev/null | head -n1 || true)"
if [[ -n "$ISO" ]]; then
  echo
  echo "============================================"
  echo " Готово: $BUILD_DIR/$ISO"
  echo " Запись на флешку (ОСТОРОЖНО, сотрёт флешку!):"
  echo "   sudo dd if=$BUILD_DIR/$ISO of=/dev/sdX bs=4M status=progress conv=fsync"
  echo " Или используйте Ventoy / balenaEtcher / Rufus (режим DD)."
  echo "============================================"
else
  echo "Сборка не удалась, смотрите $BUILD_DIR/build.log" >&2
  exit 1
fi

exit 0
__ASSETS__
H4sIAAAAAAAAA9T9f1QTV/s+jCYhkSQi5hcKCpqEJCRBbUBsCYomMUISQ8gvQBR9CD9EbGshglqp
FsKACSJCmNjAk2KIISQBqWKtSGsLERVSHwUEH7XSikpFSqm1Kq3W9kzs5z3f73vWOu9Z56z1/nEi
